package com.xiahu.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.zip.*;import org.json.*;
/** Isolated synthetic fixtures: no user account, source books or live page loads. */
public final class CompatibilityTest extends Instrumentation {
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);}
 static void field(Object owner,String name,Object value)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);f.set(owner,value);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();Context context=getTargetContext();File zip=new File(context.getCacheDir(),"compat-original.epub");final MainActivity[] host=new MainActivity[1];final WebsiteClient[] client=new WebsiteClient[1];final FrameLayout[] root=new FrameLayout[1];boolean ok=false;
 try{
  try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(zip))){z.putNextEntry(new ZipEntry("OPS/Styles/note.css"));z.write(".note{color:#c00000}".getBytes("UTF-8"));z.closeEntry();}
  LocalBooks local=new LocalBooks(context);Method styles=LocalBooks.class.getDeclaredMethod("withStyles",Uri.class,JSONObject.class);styles.setAccessible(true);JSONObject part=new JSONObject().put("entry","OPS/Text/ch.xhtml").put("html","<link rel='stylesheet' href='../Styles/note.css'/><link rel='stylesheet' href='https://example.invalid/external.css'/>");styles.invoke(local,Uri.fromFile(zip),part);check(part.getString("styles").contains("#c00000")&&!part.getString("styles").contains("external"),"Local relative EPUB stylesheet resolves inside original ZIP");
  runOnMainSync(()->host[0]=new MainActivity());SharedPreferences prefs=context.getSharedPreferences("reader_compat_state_only",0);prefs.edit().clear().commit();field(host[0],"prefs",prefs);Method save=MainActivity.class.getDeclaredMethod("saveState",JSONObject.class);save.setAccessible(true);
  JSONObject anchor=new JSONObject().put("key","i:0123456789abcdef:0").put("index",2).put("fragment",0).put("fraction",.33).put("at",.25).put("headroom",0);JSONObject progress=new JSONObject().put("index",1).put("chapterKey","fixture-chapter").put("ratio",.4).put("time",System.currentTimeMillis()).put("anchor",anchor).put("imageHints",new JSONArray().put(new JSONArray().put("0123456789abcdef").put(1.5).put(800)));
  save.invoke(host[0],new JSONObject().put("history",new JSONArray().put(new JSONObject().put("id","99").put("source","online").put("title","Original fixture"))).put("progress",new JSONObject().put("99",progress)));JSONObject saved=new JSONObject(prefs.getString("state","{}"));check(saved.getJSONArray("history").length()==1&&saved.getJSONObject("progress").getJSONObject("99").getJSONObject("anchor").getInt("index")==2&&saved.getJSONObject("progress").getJSONObject("99").getJSONArray("imageHints").length()==1,"Guest history and illustration anchor committed locally");prefs.edit().clear().commit();
  // Real Activity only supplies assets/theme; website browser is never navigated.
  Intent intent=new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=startActivitySync(intent);waitForIdleSync();runOnMainSync(()->{try{root[0]=new FrameLayout(activity);client[0]=new WebsiteClient(activity,root[0]);}catch(Exception e){throw new RuntimeException(e);}});
  CookieManager cookies=CookieManager.getInstance();CountDownLatch cleared=new CountDownLatch(1);runOnMainSync(()->cookies.removeAllCookies(v->cleared.countDown()));check(cleared.await(5,TimeUnit.SECONDS),"Fixture cookie reset");CountDownLatch set=new CountDownLatch(2);runOnMainSync(()->{cookies.setAcceptCookie(true);cookies.setCookie(WebsiteClient.BASE,"PHPSESSID=LiveSynthetic; Path=/; Secure; HttpOnly",v->set.countDown());cookies.setCookie(WebsiteClient.BASE,"cf_clearance=LiveClearanceSynthetic; Path=/; Secure",v->set.countDown());});check(set.await(5,TimeUnit.SECONDS),"Fixture cookies installed");client[0].restore("PHPSESSID=StaleSynthetic; cf_clearance=StaleClearanceSynthetic");String live=client[0].cookie();check(live.contains("PHPSESSID=LiveSynthetic")&&live.contains("cf_clearance=LiveClearanceSynthetic")&&!live.contains("Stale"),"Live browser cookies not overwritten");
  runOnMainSync(()->{check(client[0].web.getLayoutParams().width==-1&&client[0].web.getLayoutParams().height==-1,"Initial browser keeps full viewport");client[0].park(root[0]);check(client[0].web.getLayoutParams().width==-1&&client[0].web.getLayoutParams().height==-1,"Parked browser keeps full viewport");});
  CountDownLatch removed=new CountDownLatch(1);runOnMainSync(()->cookies.setCookie(WebsiteClient.BASE,"PHPSESSID=; Path=/; Secure; Max-Age=0",v->removed.countDown()));check(removed.await(5,TimeUnit.SECONDS),"Missing-session fixture");field(client[0],"restored",false);client[0].restore("PHPSESSID=FallbackSynthetic; cf_clearance=StaleClearanceSynthetic");live=client[0].cookie();check(live.contains("PHPSESSID=FallbackSynthetic")&&live.contains("cf_clearance=LiveClearanceSynthetic")&&!live.contains("Stale"),"Only missing first-party session restored; clearance preserved");client[0].persist();
  runOnMainSync(()->activity.finish());out.putString("report",new JSONObject().put("passed",true).put("localEpubRelativeCss",true).put("guestStateCommittedWithImageAnchor",true).put("liveBrowserCookiesPreserved",true).put("clearanceNotReplayedFromSnapshot",true).put("fullViewportWhileParked",true).put("realAuthenticatedLoginTested",false).toString());ok=true;
 }catch(Throwable error){out.putString("failure",error.toString());}
 finally{zip.delete();context.getSharedPreferences("reader_compat_state_only",0).edit().clear().commit();if(client[0]!=null)runOnMainSync(()->client[0].destroy());CountDownLatch done=new CountDownLatch(1);runOnMainSync(()->CookieManager.getInstance().removeAllCookies(v->done.countDown()));try{done.await(5,TimeUnit.SECONDS);}catch(Exception ignored){} }
 finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);
 }
}
